INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('749584e6-f051-59be-bacf-1889b50c5e26', '8c587e5b-dc25-5bd5-9fe1-9b69999349b7', 1, $json${"prompt":"In wildcard matching, what is the transition for dp[i][j] when p[j-1] == '*'?","multiple":false,"options":[{"id":"a","text":"dp[i][j] = dp[i][j-1] or dp[i-1][j]: the star matches zero characters, or it consumes one more character of s","is_correct":true},{"id":"b","text":"dp[i][j] = dp[i-1][j-1], the same rule as a plain character match","is_correct":false},{"id":"c","text":"dp[i][j] = dp[i-1][j-2], looking back two rows and two columns","is_correct":false},{"id":"d","text":"A star can never appear in a valid pattern, so no transition is needed","is_correct":false}],"explanation":"The star has two valid outcomes that must be OR'd together: matching zero characters of s (dp[i][j-1]) or consuming one more character while the star stays active (dp[i-1][j])."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

