INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('fd199d1c-7ea4-5ac4-9728-ab0f672cf446', '346839fb-039a-5f1a-b5c2-f3ada2557194', 1, $json${"prompt":"Why can a 2D string-comparison DP often be shrunk from O(m*n) space down to O(n)?","multiple":false,"options":[{"id":"a","text":"Each row of the table only ever reads values from the row directly above it, so only the previous row needs to be kept","is_correct":true},{"id":"b","text":"Because strings are always shorter than 100 characters","is_correct":false},{"id":"c","text":"Because Python automatically compresses 2D arrays","is_correct":false},{"id":"d","text":"It can't be shrunk; O(m*n) space is always required","is_correct":false}],"explanation":"If dp[i][j] only depends on row i-1 (and possibly the current row), a rolling pair of 1D arrays is enough, since older rows are never read again."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

