VALUES ('851ad664-2908-5f6f-a714-b68a06aa229e', '90c89f5a-7178-58bb-9172-4ea9683f8935', 1, $json${"prompt":"What does the CAP theorem say a distributed system must choose between during a network partition?","multiple":false,"options":[{"id":"a","text":"Consistency or availability — you cannot have both while partitioned","is_correct":true},{"id":"b","text":"Latency or throughput","is_correct":false},{"id":"c","text":"Durability or atomicity","is_correct":false},{"id":"d","text":"Nothing — modern databases avoid the trade-off entirely","is_correct":false}],"explanation":"When nodes can't communicate, you either reject requests to stay consistent (CP) or serve possibly-stale data to stay available (AP). Partition tolerance itself is non-negotiable."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

