INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('2a2005c5-083c-5bb4-8b22-190db94efddd', 'b98e439a-649a-5e23-a728-36092eb33db8', 1, $json${"prompt":"On a database write, why is deleting the matching cache key usually safer than overwriting it with the new value?","multiple":false,"options":[{"id":"a","text":"Two concurrent writers can overwrite the cache in the wrong order and leave a stale value stuck there forever; deleting forces the next read to repopulate from the real data","is_correct":true},{"id":"b","text":"Deleting uses less memory than overwriting","is_correct":false},{"id":"c","text":"Redis does not support overwriting an existing key","is_correct":false},{"id":"d","text":"Overwriting always causes a cache miss anyway","is_correct":false}],"explanation":"If writer A's slower update lands after writer B's faster one, an overwrite leaves the older value cached permanently. A delete has no such race: the next read simply goes to the source of truth."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

