INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('4949e1fd-d7c1-5cf1-a315-f2c7ff4e30e7', '3a4a49ed-4e24-54d2-9a78-c0e6c75de7a8', 1, $json${"prompt":"You shard a table by `order_id`, but 95% of queries ask for \"all orders placed by customer X.\" What goes wrong?","multiple":false,"options":[{"id":"a","text":"Almost every common query becomes a scatter-gather across all shards, so latency tracks the slowest shard instead of any single one","is_correct":true},{"id":"b","text":"Nothing, because hash partitioning always distributes evenly","is_correct":false},{"id":"c","text":"The orders lose their uniqueness guarantee","is_correct":false},{"id":"d","text":"Replication lag increases automatically","is_correct":false}],"explanation":"Even distribution is only half of choosing a partition key. The other half is aligning the key with your dominant query — here that would be customer_id, not order_id."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
