INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('bf25af78-7002-572e-b7b9-e96d4dc1cc15', 'c3502087-9202-55a8-8cc7-04c56c31c415', 1, $json${"prompt":"Three independent teams — billing, analytics, and search — each need to process every order event, and search wants to replay all of history next month to rebuild its index. What fits best?","multiple":false,"options":[{"id":"a","text":"A distributed log (like Kafka), where each team is its own consumer group with its own offset, and retention makes replay possible","is_correct":true},{"id":"b","text":"A single message queue with three consumers splitting the messages between them","is_correct":false},{"id":"c","text":"Direct synchronous HTTP calls from the order service to all three teams","is_correct":false},{"id":"d","text":"A shared table that all three teams poll","is_correct":false}],"explanation":"A queue deletes a message once any one consumer takes it, so three consumers on one queue would only see a third of the events each. A log retains everything and lets each consumer group read at its own pace, including replaying from the start."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

