INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('3fd10289-6c69-50fe-9679-b705cad6c764', '5e464134-a775-5d53-9c0b-c01bb0b58648', 1, $json${"prompt":"Why do production Raft or Paxos clusters almost always use an odd number of nodes, such as 3 or 5, instead of an even number like 4?","multiple":false,"options":[{"id":"a","text":"An even-sized cluster needs the same majority as the next odd size down, so the extra node adds cost and latency without adding fault tolerance","is_correct":true},{"id":"b","text":"Consensus algorithms mathematically require a prime number of nodes","is_correct":false},{"id":"c","text":"Even-sized clusters cannot elect a leader at all","is_correct":false},{"id":"d","text":"Odd numbers are simply a long-standing convention with no technical reason","is_correct":false}],"explanation":"A majority of 4 nodes is 3, and a majority of 5 nodes is also 3 — so a 4-node cluster tolerates only 1 failure, exactly like a 3-node cluster, while costing one extra machine and one extra vote's worth of latency."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

