INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('b18b9206-56a6-5898-af27-337884c5c8e6', '87dbb233-63f7-5d11-a915-d8fc5541b0ec', 1, $json${"prompt":"A \"100 requests per minute\" limiter uses a fixed window that resets every 60 seconds. What is its known weakness?","multiple":false,"options":[{"id":"a","text":"A client can send 100 requests in the last second of one window and another 100 in the first second of the next, getting 200 requests in about one second","is_correct":true},{"id":"b","text":"It uses far more memory than every other rate-limiting algorithm","is_correct":false},{"id":"c","text":"It cannot be implemented using Redis","is_correct":false},{"id":"d","text":"It never actually enforces the stated limit","is_correct":false}],"explanation":"Fixed windows reset sharply at a clean boundary, so a client that times its bursts around the boundary can briefly send close to double the intended rate. Token bucket and the sliding window counter both avoid this boundary spike."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

