INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('0c6952a4-09bc-5da6-b49a-17bf659f0674', 'c56fde71-978a-5ea1-a17c-336f73794fc8', 1, $json${"prompt":"An e-commerce system needs to never oversell the last item in stock, but is fine showing a slightly outdated review count. What is the strongest way to describe this in CAP terms?","multiple":false,"options":[{"id":"a","text":"The stock-decrement operation should be CP (refuse rather than risk an overselling error) while the review count can be AP (stay available and reconcile later)","is_correct":true},{"id":"b","text":"The whole system should be built as CP, since money is involved somewhere","is_correct":false},{"id":"c","text":"The whole system should be built as AP, since availability matters most to users","is_correct":false},{"id":"d","text":"CAP does not apply here because there is only one database","is_correct":false}],"explanation":"CAP is a choice you make per operation, not once for an entire system. The same system can refuse-rather-than-risk-wrong for inventory while staying available-and-reconciling for a cosmetic count like reviews."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

