INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('4b361bcc-953d-557b-b1c9-91d9941bb53d', 'aabe327d-aec7-5080-b722-5d69d4a02fc8', 1, $json${"prompt":"Which design pattern lets you swap algorithms at runtime behind one interface — for example, several payment providers behind one checkout method?","multiple":false,"options":[{"id":"a","text":"Strategy","is_correct":true},{"id":"b","text":"Singleton","is_correct":false},{"id":"c","text":"Decorator","is_correct":false},{"id":"d","text":"Observer","is_correct":false}],"explanation":"Strategy wraps interchangeable behaviours behind one common interface, chosen at runtime. Decorator adds responsibilities, Observer broadcasts events to listeners, and Singleton restricts a class to exactly one instance."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
