INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('2caf9b4d-acf4-5778-854f-ca088c827b27', '9fbc7aa6-484b-5674-91c5-9a216a38e14c', 1, $json${"prompt":"A `Dog` and a `Boat` both need a `swim()` method, but a `Boat` is clearly not an `Animal`. What does this call for?","multiple":false,"options":[{"id":"a","text":"An abstract class, since both types share behaviour","is_correct":false},{"id":"b","text":"An interface (or a Python Protocol) — this is a CAN-DO relationship between unrelated types, with no shared implementation","is_correct":true},{"id":"c","text":"Multiple inheritance from a shared Animal base","is_correct":false},{"id":"d","text":"A Singleton that both types depend on","is_correct":false}],"explanation":"Abstract class means IS-A, sharing both a type relationship and some implementation. Interface means CAN-DO — unrelated types promising the same capability with no shared code, which is exactly the Dog/Boat situation."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

