INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('83adc277-b7e0-503d-80df-323fa4784653', '00000000-0000-0000-0000-000000000001', 'mcq', 'Why does a thread-safe Singleton use double-checked locking instead of lockin...', 'advanced', 15, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
