INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('61f91db1-78d9-54cf-ac01-5b266253563c', '83adc277-b7e0-503d-80df-323fa4784653', 1, $json${"prompt":"Why does a thread-safe Singleton use double-checked locking instead of locking on every single access?","multiple":false,"options":[{"id":"a","text":"To make the singleton object immutable","is_correct":false},{"id":"b","text":"So the lock is only ever taken during the first, racing construction — later accesses skip locking entirely, while the inner check stops two threads that both passed the outer check from building two instances","is_correct":true},{"id":"c","text":"To allow more than one instance to exist when needed","is_correct":false},{"id":"d","text":"Because constructors cannot be synchronized in most languages","is_correct":false}],"explanation":"A single check alone races; locking on every access works but pays a permanent cost on a read-mostly path. Check, lock, check again gives correctness while paying the synchronisation cost only once."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

