INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('640775d0-d818-5cb7-848e-bc1031f339ac', '039b1aa3-cc95-5ebb-883c-81f51a559dca', 1, $json${"prompt":"Proxy and Decorator have nearly identical class diagrams. What actually tells them apart?","multiple":false,"options":[{"id":"a","text":"Proxy can only wrap one object; Decorator can wrap several","is_correct":false},{"id":"b","text":"Intent: Decorator adds new behaviour and the caller deliberately stacks it; Proxy controls access to the same behaviour and is usually invisible to the caller","is_correct":true},{"id":"c","text":"Decorators run at compile time, proxies at runtime","is_correct":false},{"id":"d","text":"Proxies never implement the same interface as the object they wrap","is_correct":false}],"explanation":"These patterns are classified by intent, not by shape. Decorator deliberately adds behaviour; Proxy controls access — lazy loading, permission checks, caching, or a remote stand-in — usually without the caller even knowing."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('d0b390d6-f402-5c7e-8243-460c5ae66337', '00000000-0000-0000-0000-000000000001', 'mcq', 'What''s the most common memory bug in an Observer implementation?', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('9b3f7cdf-0dfd-54cb-8628-d880a26290ef', 'd0b390d6-f402-5c7e-8243-460c5ae66337', 1, $json${"prompt":"What's the most common memory bug in an Observer implementation?","multiple":false,"options":[{"id":"a","text":"The subject stores too many past events","is_correct":false},{"id":"b","text":"Observers are never unsubscribed, so the subject's strong references keep them alive indefinitely","is_correct":true},{"id":"c","text":"Observers get notified in the wrong order","is_correct":false},{"id":"d","text":"The observer interface has too many methods","is_correct":false}],"explanation":"A long-lived subject holding references to short-lived observers stops garbage collection from ever cleaning them up. Every subscribe needs a matching unsubscribe, or weak references instead."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('28b74b9e-94ed-500f-8055-24a82ebd8c92', '00000000-0000-0000-0000-000000000001', 'mcq', 'What''s the clearest way to tell Strategy and State apart?', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
