INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('529db4b5-28a5-5630-9f1b-3e32a4bbc08b', '28b74b9e-94ed-500f-8055-24a82ebd8c92', 1, $json${"prompt":"What's the clearest way to tell Strategy and State apart?","multiple":false,"options":[{"id":"a","text":"Strategy uses interfaces; State uses enums","is_correct":false},{"id":"b","text":"With Strategy, whoever's using the object picks an independent algorithm; with State, the object's own states drive transitions between each other, modelling a lifecycle","is_correct":true},{"id":"c","text":"Strategy is a creational pattern, State is a structural one","is_correct":false},{"id":"d","text":"State can only ever have exactly two possible values","is_correct":false}],"explanation":"Strategy and State have nearly identical class diagrams, so intent separates them. Strategies are picked from outside and stand alone; states know their own successors and drive transitions from within."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

