INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('5f1024ee-e881-567f-83af-ee3e395e3a48', '8aac2f74-1129-5e01-b2cd-8ef0bd0fe7c2', 1, $json${"prompt":"A booking service runs on five separate servers. Which mechanism actually stops a seat from being double-booked?","multiple":false,"options":[{"id":"a","text":"A synchronized method or a threading.Lock inside the booking service","is_correct":false},{"id":"b","text":"A conditional database write, checked and applied atomically, with a unique constraint as a backstop — an in-process lock only synchronises threads within one single process","is_correct":true},{"id":"c","text":"Making the Seat class immutable","is_correct":false},{"id":"d","text":"Ordering in-process locks by seat id","is_correct":false}],"explanation":"In-process locks are invisible to a different process entirely. Only the database, which every server shares, can arbitrate between them — through a conditional write and a unique constraint."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
