INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('b8ddba20-ed0a-5ada-912f-27656371b544', '7ef43382-d85d-5d6a-babd-b13e6d4c0ad2', 1, $json${"prompt":"Two threads transfer money in opposite directions between accounts A and B, each locking the source account and then the destination. What's the standard fix?","multiple":false,"options":[{"id":"a","text":"Use one single global lock for every transfer in the system","is_correct":false},{"id":"b","text":"Lock the two accounts in a fixed global order — by account id, for instance — which breaks the circular-wait condition while still allowing unrelated transfers to run in parallel","is_correct":true},{"id":"c","text":"Make the Account class immutable","is_correct":false},{"id":"d","text":"Retry the transfer automatically if it seems to be taking too long","is_correct":false}],"explanation":"A single global lock works but forces every transfer in the system to wait its turn. Locking in a consistent order removes the circular wait with no loss of parallelism."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

