INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('bd72e025-625f-5ed6-a3dd-6f37db90436f', '714cb36a-5e02-5f08-8ebc-dac1268f75d3', 1, $json${"prompt":"Two objects reference only each other, and nothing else in the program references either one. Which mechanism actually frees them?","multiple":false,"options":[{"id":"a","text":"The cyclic garbage collector, since reference counting alone never reaches zero for a cycle","is_correct":true},{"id":"b","text":"Reference counting alone, the instant the last del runs","is_correct":false},{"id":"c","text":"Neither; Python leaks the pair until the process exits","is_correct":false},{"id":"d","text":"The GIL frees them as part of releasing the lock","is_correct":false}],"explanation":"Each object in a two-way cycle keeps a refcount of at least 1 from the other, so plain reference counting never reaches zero. The cyclic collector detects that the only references left are internal to the cycle and frees both."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

