VALUES ('90a5e0a3-459a-5e8d-859c-7a08b6c63f8b', '00000000-0000-0000-0000-000000000001', 'mcq', 'An async def route calls a blocking synchronous function (e.g. a sync DB driv...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
