INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('9a3ae395-5d61-5a81-a993-6f9974c924cb', '90a5e0a3-459a-5e8d-859c-7a08b6c63f8b', 1, $json${"prompt":"An async def route calls a blocking synchronous function (e.g. a sync DB driver). What actually breaks?","multiple":false,"options":[{"id":"a","text":"Only that one request is slow; other requests are unaffected","is_correct":false},{"id":"b","text":"The entire event loop is blocked, so every other concurrent request on that worker stalls until the blocking call returns","is_correct":true},{"id":"c","text":"FastAPI automatically detects and thread-pools it, exactly like a plain def route","is_correct":false},{"id":"d","text":"Nothing; async def and def behave identically for blocking calls","is_correct":false}],"explanation":"A single-threaded event loop drives every coroutine on that worker by yielding at await points. A blocking call never yields, so it holds the whole loop hostage, stalling every other request being served by that worker."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

