INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('c432f945-c12e-51fa-a827-ec0c6c211c6a', 'afd5faba-fb2b-5fec-a0c9-e503ef16af4d', 1, $json${"prompt":"Three independent upstream calls each take 200 ms. What is the approximate total time using asyncio.gather versus awaiting them one after another?","multiple":false,"options":[{"id":"a","text":"About 200 ms with gather (the max), versus about 600 ms sequentially (the sum)","is_correct":true},{"id":"b","text":"Both take about 600 ms","is_correct":false},{"id":"c","text":"gather takes longer due to scheduling overhead","is_correct":false},{"id":"d","text":"About 67 ms with gather","is_correct":false}],"explanation":"asyncio.gather starts all three coroutines at once, so total latency tracks the slowest single call. Sequential awaits pay for each call's latency one after another."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

