INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('863eb0d1-984b-508a-95bd-39bf2c6e90fe', '2acd1b55-48d4-5dff-ad54-81e89ba74e07', 1, $json${"prompt":"A team needs an API-first service with heavy concurrent I/O and wants validation/docs generated automatically from type hints. Which framework fits, and why?","multiple":false,"options":[{"id":"a","text":"FastAPI, since ASGI concurrency suits I/O-bound work and Pydantic generates validation/OpenAPI docs from type hints","is_correct":true},{"id":"b","text":"Django, for its built-in admin panel","is_correct":false},{"id":"c","text":"Flask, since it has the least code to learn","is_correct":false},{"id":"d","text":"All three are equally suited to this use case","is_correct":false}],"explanation":"FastAPI's async-first ASGI model targets exactly this workload, and its Pydantic integration gives automatic validation and OpenAPI docs from the same type hints, with no separate documentation effort."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
