INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('002b4b36-a8d8-5f01-a17f-371b7899b90b', '63e410e0-cb45-5e13-901c-1e0aec0590b7', 1, $json${"prompt":"Without @lru_cache, does FastAPI's default dependency caching make get_settings run only once across the whole app's lifetime?","multiple":false,"options":[{"id":"a","text":"Yes, FastAPI caches every dependency for the life of the process","is_correct":false},{"id":"b","text":"No, the cache only lasts one request; get_settings runs again on each new request unless wrapped in something like @lru_cache","is_correct":true},{"id":"c","text":"No, FastAPI never caches dependencies at all","is_correct":false},{"id":"d","text":"Yes, but only for class-based dependencies","is_correct":false}],"explanation":"FastAPI's built-in dependency cache is scoped to a single request, so two dependencies sharing get_settings within one request only trigger it once, but a new request runs it again from scratch."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

