INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('1973bff6-c881-51c5-b22b-cc28afdce2d8', '8e993b5b-37d7-5165-b906-2d15344990a9', 1, $json${"prompt":"In a `yield`-based dependency like `def get_db(): db = SessionLocal(); yield db; db.close()`, when does db.close() run?","multiple":false,"options":[{"id":"a","text":"Before the endpoint body executes","is_correct":false},{"id":"b","text":"After the endpoint has finished and the response has been sent","is_correct":true},{"id":"c","text":"Only if an exception is raised","is_correct":false},{"id":"d","text":"It never runs automatically","is_correct":false}],"explanation":"Everything before yield is setup, injected into the endpoint. Everything after yield is teardown, which FastAPI runs once the request/response cycle completes."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
