ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('5a737c7c-f266-58c9-b501-7e04f2cf1f9c', 'f24f22bd-67a4-5477-b6eb-26a049cab4d7', 1, $json${"prompt":"In a job queue system, how do you safely handle a worker that dies mid-task?","multiple":false,"options":[{"id":"a","text":"Use visibility timeouts / heartbeats so the job returns to the queue, and make task handlers idempotent","is_correct":true},{"id":"b","text":"Mark the job completed as soon as a worker picks it up","is_correct":false},{"id":"c","text":"Delete the job when the worker crashes","is_correct":false},{"id":"d","text":"Rely on the worker to always finish","is_correct":false}],"explanation":"Acknowledge only after completion; if the worker's lease or heartbeat lapses, the broker redelivers. Because redelivery means possible re-execution, handlers must be idempotent, the core Celery interview answer."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('528a0675-14fa-5171-8b6e-4be5a9828e82', '00000000-0000-0000-0000-000000000001', 'mcq', 'What is the classic failure mode of a Redis distributed lock with a TTL?', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('cf5a34bc-c595-5553-8d87-38a9c4034996', '528a0675-14fa-5171-8b6e-4be5a9828e82', 1, $json${"prompt":"What is the classic failure mode of a Redis distributed lock with a TTL?","multiple":false,"options":[{"id":"a","text":"A paused/slow client's lock expires, another client acquires it, and both run the critical section","is_correct":true},{"id":"b","text":"The lock can never expire, causing deadlock","is_correct":false},{"id":"c","text":"Redis rejects SET NX under load","is_correct":false},{"id":"d","text":"TTL locks prevent all concurrency bugs","is_correct":false}],"explanation":"If the holder stalls (a GC pause, network delay) past the TTL, the lock is released while it still thinks it owns it. Mitigations: fencing tokens, lock renewal (watchdog), or accepting at-least-once semantics with idempotency."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('c3072966-496a-5c52-93f8-8e4fa089b6ca', '00000000-0000-0000-0000-000000000001', 'mcq', 'After updating a row in the database, why delete the matching cache key inste...', 'beginner', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('94678cb5-f430-58b7-bf52-dff997116e5c', 'c3072966-496a-5c52-93f8-8e4fa089b6ca', 1, $json${"prompt":"After updating a row in the database, why delete the matching cache key instead of writing the new value into the cache directly?","multiple":false,"options":[{"id":"a","text":"Deleting forces the next read to fetch the real value from the source of truth, avoiding a race where an out-of-order write leaves a stale value stuck in the cache","is_correct":true},{"id":"b","text":"Deleting is always a faster Redis operation than SET","is_correct":false},{"id":"c","text":"Redis does not allow overwriting an existing key","is_correct":false},{"id":"d","text":"There is no real difference between the two approaches","is_correct":false}],"explanation":"Two writers updating the cache directly can land in the wrong order, leaving the older value stuck. Deleting removes that possibility: the worst case is one extra cache miss, not a permanently wrong value."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

