INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('3740cae4-13d6-51dc-94fc-db87f6466091', '41fc3d12-706b-5b0f-a81b-3bbdc80e3248', 1, $json${"prompt":"A Redis instance holds both disposable cache entries and session data that must never be silently evicted. Which family of eviction policy fits?","multiple":false,"options":[{"id":"a","text":"allkeys-lru","is_correct":false},{"id":"b","text":"volatile-lru, since it only evicts keys that were explicitly given a TTL","is_correct":true},{"id":"c","text":"noeviction","is_correct":false},{"id":"d","text":"allkeys-random","is_correct":false}],"explanation":"A volatile-* policy only considers TTL'd keys for eviction, leaving untimed data like session state untouched under memory pressure."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

