INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('4cdc5ae7-43e2-51c1-9037-dad78a45a5d3', 'd48561b2-f8e4-5eae-8d31-319120f05726', 1, $json${"prompt":"Why does a Redis sorted set fit a leaderboard better than repeatedly re-sorting a plain list?","multiple":false,"options":[{"id":"a","text":"It combines a skip list for fast ordered range reads with a hash table for fast lookup by member, keeping order incrementally instead of re-sorting","is_correct":true},{"id":"b","text":"Sorted sets store data in a random order for security","is_correct":false},{"id":"c","text":"Sorted sets can only hold string values","is_correct":false},{"id":"d","text":"Lists in Redis cannot store more than 100 items","is_correct":false}],"explanation":"A ZSET's skip-list-plus-hash-table structure keeps members in order as scores change, giving fast ranked reads without a fresh sort on every update."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('0f3c6c9a-2913-562f-bb07-b828c973399c', '00000000-0000-0000-0000-000000000001', 'mcq', 'A subscriber disconnects for 30 seconds while messages are sent. What is the ...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
