INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('7eb11eec-14c5-5c9c-a8e2-7cbff7df9e8a', '0f3c6c9a-2913-562f-bb07-b828c973399c', 1, $json${"prompt":"A subscriber disconnects for 30 seconds while messages are sent. What is the key difference between Redis streams and pub/sub here?","multiple":false,"options":[{"id":"a","text":"A stream persists the entries, so the consumer can catch up on reconnecting; pub/sub delivers only to whoever is listening right now and drops the rest","is_correct":true},{"id":"b","text":"Both mechanisms behave identically in this scenario","is_correct":false},{"id":"c","text":"Pub/sub persists messages; streams do not","is_correct":false},{"id":"d","text":"Neither mechanism can recover from any disconnect","is_correct":false}],"explanation":"Streams are durable, append-only logs a consumer can replay. Pub/sub is fire-and-forget: a message sent while nobody is subscribed is gone immediately."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('1f6a3bf9-b91d-5c5f-b3fd-bea7735f682e', '00000000-0000-0000-0000-000000000001', 'mcq', 'Celery''s default delivery guarantee is at-least-once, not exactly-once. What ...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('4165ebb8-f65a-5a84-a3e6-8d740a7339cc', '1f6a3bf9-b91d-5c5f-b3fd-bea7735f682e', 1, $json${"prompt":"Celery's default delivery guarantee is at-least-once, not exactly-once. What does that require of every task?","multiple":false,"options":[{"id":"a","text":"The task's side effect must be idempotent, since redelivery can cause it to run more than once","is_correct":true},{"id":"b","text":"Nothing extra; Celery guarantees each task runs exactly once by default","is_correct":false},{"id":"c","text":"Every task must be wrapped in a database transaction","is_correct":false},{"id":"d","text":"Tasks must never call external APIs","is_correct":false}],"explanation":"At-least-once delivery means a worker crash after execution but before acking can cause the same task message to be redelivered and re-run. The task's effect, not the delivery mechanism, has to tolerate that."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

