INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('075f1672-159a-5c0a-9ab8-c8297b982066', 'fe3eba60-56f5-5af7-97a7-559c970ddb2b', 1, $json${"prompt":"A system needs every event for one order processed in order, but doesn't care about ordering between different orders. What's the standard Kafka approach?","multiple":false,"options":[{"id":"a","text":"Key each event by order_id, so all of one order's events land in the same partition and stay ordered, while different orders spread across partitions","is_correct":true},{"id":"b","text":"Use exactly one partition for the whole topic","is_correct":false},{"id":"c","text":"Kafka guarantees global ordering automatically across all partitions","is_correct":false},{"id":"d","text":"Use a separate consumer group for every order","is_correct":false}],"explanation":"Kafka only orders records within a single partition. Keying by the entity that needs ordering routes its events to one partition consistently, without capping the whole topic to one partition's throughput."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('e755acf7-3308-5d20-804b-071d48236a4c', '00000000-0000-0000-0000-000000000001', 'mcq', 'Why does writing an event to an outbox table in the same transaction as the b...', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('a0c0888e-5400-5134-9884-dbaf3c40ae31', 'e755acf7-3308-5d20-804b-071d48236a4c', 1, $json${"prompt":"Why does writing an event to an outbox table in the same transaction as the business write solve the 'DB commits but the event is never published' problem?","multiple":false,"options":[{"id":"a","text":"The event's existence becomes tied to the business write actually committing, since both are in one transaction; a separate relay process then publishes it, which is why the consumer still needs to be idempotent","is_correct":true},{"id":"b","text":"It guarantees the event is published instantly, with no relay process needed","is_correct":false},{"id":"c","text":"It replaces the need for a message broker entirely","is_correct":false},{"id":"d","text":"It only works if the business write and the event go to different databases","is_correct":false}],"explanation":"The transactional write guarantees the outbox row exists if and only if the business data committed. Actual delivery still happens afterward through a relay, which can itself fail partway, so outbox alone gives at-least-once delivery."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

