INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('37129136-bca7-58ee-824e-d07c2826f3f2', '9493c8fc-94cb-5c94-a9c4-da05d7eaeebc', 1, $json${"prompt":"During an actual network partition, a payments ledger refuses to accept a write it cannot confirm is durable across nodes. What choice does this represent?","multiple":false,"options":[{"id":"a","text":"CP: choosing consistency over availability during the partition","is_correct":true},{"id":"b","text":"AP: choosing availability over consistency","is_correct":false},{"id":"c","text":"This has nothing to do with CAP theorem","is_correct":false},{"id":"d","text":"Partition tolerance is being sacrificed here","is_correct":false}],"explanation":"Refusing a write it can't confirm is durable, rather than risking two diverging values, is the CP choice: sacrificing availability to preserve consistency during the partition."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('d6deb044-83a6-5b1b-b08a-1c81ae5e3bb0', '00000000-0000-0000-0000-000000000001', 'mcq', 'Why does full jitter (a random delay between 0 and the backoff ceiling) beat ...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
