INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('43ef564c-0b1d-50ba-9b68-13eccef580af', 'd6deb044-83a6-5b1b-b08a-1c81ae5e3bb0', 1, $json${"prompt":"Why does full jitter (a random delay between 0 and the backoff ceiling) beat a fixed exponential delay when many clients fail at once?","multiple":false,"options":[{"id":"a","text":"It decorrelates retry timing across clients, so they don't all retry at the exact same moment and re-overwhelm the recovering service","is_correct":true},{"id":"b","text":"It makes each individual client retry faster overall","is_correct":false},{"id":"c","text":"It eliminates the need for a maximum retry count","is_correct":false},{"id":"d","text":"It only matters when there is exactly one client retrying","is_correct":false}],"explanation":"A fixed exponential delay computed from the same failure moment means every client retries in lockstep. Full jitter spreads retries across a range, avoiding a second synchronized spike."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('4296e9b4-c6c9-540b-9cda-a37739b52a42', '00000000-0000-0000-0000-000000000001', 'mcq', 'What problem does a fencing token solve that a Redlock-style lock alone does ...', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('8d34e5e5-cbc2-5fc5-b52d-7784000e2517', '4296e9b4-c6c9-540b-9cda-a37739b52a42', 1, $json${"prompt":"What problem does a fencing token solve that a Redlock-style lock alone does not?","multiple":false,"options":[{"id":"a","text":"It stops a stale write from a former lock holder from still landing on the protected resource, since the resource itself rejects any token lower than the last one it accepted","is_correct":true},{"id":"b","text":"It eliminates the need for a TTL on the lock entirely","is_correct":false},{"id":"c","text":"It makes lock acquisition faster across multiple Redis nodes","is_correct":false},{"id":"d","text":"It replaces the need for a quorum of instances","is_correct":false}],"explanation":"A lock only tracks who currently holds it, not whether a delayed write from a former holder still arrives. A fencing token lets the protected resource itself enforce ordering, rejecting stale writes regardless of what the lock currently shows."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

