INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('5c516235-8bd0-585a-87e9-3e642ad179ff', '6c721ace-869a-5a57-afca-53ad9f206546', 1, $json${"prompt":"Which defense stops most CSRF attacks today with the least implementation effort?","multiple":false,"options":[{"id":"a","text":"Setting SameSite=Lax or SameSite=Strict on session cookies","is_correct":true},{"id":"b","text":"Encrypting the request body","is_correct":false},{"id":"c","text":"Rate limiting every endpoint","is_correct":false},{"id":"d","text":"Requiring HTTPS on all requests","is_correct":false}],"explanation":"SameSite cookies block a cookie from being auto-attached on a cross-site request in the first place, which stops most CSRF today with a one-line cookie setting. HTTPS protects data in transit but does nothing against CSRF specifically."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('f90cf40f-348a-5317-8d9e-051cf1c6f713', '00000000-0000-0000-0000-000000000001', 'mcq', 'In the standard presigned-URL upload flow, what does the client actually rece...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('d21002f1-652b-51dc-802d-fdffdf71577b', 'f90cf40f-348a-5317-8d9e-051cf1c6f713', 1, $json${"prompt":"In the standard presigned-URL upload flow, what does the client actually receive from your server?","multiple":false,"options":[{"id":"a","text":"A signed, time-limited URL scoped to one bucket, key, and content type, which the client PUTs the file bytes to directly","is_correct":true},{"id":"b","text":"The server's raw AWS credentials","is_correct":false},{"id":"c","text":"A copy of the file, pre-uploaded by the server","is_correct":false},{"id":"d","text":"A permanent, unscoped upload URL that never expires","is_correct":false}],"explanation":"The server never sends AWS credentials to the client. It signs a time-limited URL scoped to one exact bucket, key, and content type; the client uploads directly to S3 with a plain PUT, and the server's own storage never touches the file bytes."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('990c2f34-7955-563f-ae21-163bbc4bbb77', '00000000-0000-0000-0000-000000000001', 'mcq', 'What changed about S3''s consistency model in December 2020?', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('5008fc79-487e-549f-b38f-c05e15e92514', '990c2f34-7955-563f-ae21-163bbc4bbb77', 1, $json${"prompt":"What changed about S3's consistency model in December 2020?","multiple":false,"options":[{"id":"a","text":"All S3 operations became strongly read-after-write consistent, including overwrite PUTs and deletes, which were previously only eventually consistent","is_correct":true},{"id":"b","text":"S3 switched from strong consistency to eventual consistency for all operations","is_correct":false},{"id":"c","text":"S3 began supporting multipart uploads for the first time","is_correct":false},{"id":"d","text":"S3 removed support for presigned URLs","is_correct":false}],"explanation":"Before December 2020, an overwrite PUT or a delete was only eventually consistent, so a GET right after could briefly return stale data. AWS made every S3 operation strongly read-after-write consistent from that point on."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('545649a0-2b98-5030-91ee-082b9e8b5e5e', '00000000-0000-0000-0000-000000000001', 'mcq', 'An S3 upload fails with a SlowDown error. What''s the correct response?', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('b255b603-89c2-5cb2-8dc2-fd1e364cb840', '545649a0-2b98-5030-91ee-082b9e8b5e5e', 1, $json${"prompt":"An S3 upload fails with a SlowDown error. What's the correct response?","multiple":false,"options":[{"id":"a","text":"Retry with exponential backoff, since SlowDown means you're being throttled, a transient condition","is_correct":true},{"id":"b","text":"Fail immediately, since SlowDown always means a permanent misconfiguration","is_correct":false},{"id":"c","text":"Delete the bucket and recreate it","is_correct":false},{"id":"d","text":"Ignore the error entirely, since S3 retries automatically","is_correct":false}],"explanation":"SlowDown is a transient, throttling-related error, retried with exponential backoff. Permanent errors like AccessDenied or NoSuchBucket should fail immediately instead, since retrying won't change the outcome."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('639bc7dd-cd42-57b2-8d18-2395af848859', '00000000-0000-0000-0000-000000000001', 'mcq', 'Why does copying requirements.txt and running pip install before COPY . . spe...', 'beginner', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('6a05cf7f-a54f-5ea7-97f7-d228447e96d3', '639bc7dd-cd42-57b2-8d18-2395af848859', 1, $json${"prompt":"Why does copying requirements.txt and running pip install before COPY . . speed up repeated Docker builds?","multiple":false,"options":[{"id":"a","text":"It keeps the dependency install layer cached across ordinary source code changes, since only a change to requirements.txt itself invalidates it","is_correct":true},{"id":"b","text":"It makes pip install run in parallel automatically","is_correct":false},{"id":"c","text":"It reduces the number of layers in the final image","is_correct":false},{"id":"d","text":"Docker requires requirements.txt to be copied first by convention","is_correct":false}],"explanation":"Docker caches each layer by its inputs' hash. Copying requirements.txt first means only a real dependency change invalidates the install layer; an ordinary source code edit afterward leaves that expensive layer cached."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('3b2318b4-85e4-5700-bf4f-89941b3df940', '00000000-0000-0000-0000-000000000001', 'mcq', 'What does a multi-stage Docker build actually remove from the final image, us...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('3d6658bb-06b1-5e5e-9508-272ea09b6751', '3b2318b4-85e4-5700-bf4f-89941b3df940', 1, $json${"prompt":"What does a multi-stage Docker build actually remove from the final image, using the psycopg2/build-essential example?","multiple":false,"options":[{"id":"a","text":"The compiler toolchain (build-essential, dev headers) used only to compile the package; the final stage copies just the already-compiled result","is_correct":true},{"id":"b","text":"The Python interpreter itself","is_correct":false},{"id":"c","text":"All application source code","is_correct":false},{"id":"d","text":"The base image's operating system","is_correct":false}],"explanation":"A multi-stage build isolates the compiler toolchain needed to build a package like psycopg2 from source in one stage. The final runtime stage copies only the compiled output, never the compiler or headers that produced it."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('6b2022f0-7890-5e3e-bb14-6af3e589b2af', '00000000-0000-0000-0000-000000000001', 'mcq', 'What''s the practical difference between depends_on alone and depends_on with ...', 'beginner', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('b686f01f-02bf-5346-b318-9b5fe933f975', '6b2022f0-7890-5e3e-bb14-6af3e589b2af', 1, $json${"prompt":"What's the practical difference between depends_on alone and depends_on with condition: service_healthy in docker-compose?","multiple":false,"options":[{"id":"a","text":"Plain depends_on only waits for a container to start; condition: service_healthy waits for its healthcheck to actually pass, meaning it's ready","is_correct":true},{"id":"b","text":"They behave identically in every version of Compose","is_correct":false},{"id":"c","text":"condition: service_healthy is slower but otherwise identical","is_correct":false},{"id":"d","text":"Plain depends_on only works for database containers","is_correct":false}],"explanation":"A database container can be 'started' well before it's accepting connections. Plain depends_on only orders container start; condition: service_healthy waits for a defined healthcheck to pass before starting the dependent service."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('9d14cd99-0885-561d-8b28-f6799cb517ad', '00000000-0000-0000-0000-000000000001', 'mcq', 'User A is connected to server 1 and user B to server 2, behind a load balance...', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('1a5e61c9-350d-5b3e-b3dc-6513056579e4', '9d14cd99-0885-561d-8b28-f6799cb517ad', 1, $json${"prompt":"User A is connected to server 1 and user B to server 2, behind a load balancer with no sticky sessions. A naive in-process ConnectionManager cannot let A message B. What fixes this?","multiple":false,"options":[{"id":"a","text":"A shared pub/sub backbone (Redis Pub/Sub or Kafka) that every server subscribes to, so any instance can publish a message that reaches whichever instance holds the recipient's socket","is_correct":true},{"id":"b","text":"Increasing the WebSocket connection timeout","is_correct":false},{"id":"c","text":"Switching from WebSocket to Server-Sent Events","is_correct":false},{"id":"d","text":"Running the ConnectionManager on the load balancer itself","is_correct":false}],"explanation":"A WebSocket connection is sticky to the one process that accepted it. A shared pub/sub channel that every instance subscribes to is what lets a message published from any server reach the specific instance holding the recipient's live connection."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
