INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('f78ee486-dff9-59ba-8de3-003f38064892', '2d92c857-97d6-5115-b2aa-e62e030eede9', 1, $json${"prompt":"A test replaces a dependency to verify that send_email() was called exactly once with the correct arguments. Is this dependency being used as a mock or a stub?","multiple":false,"options":[{"id":"a","text":"A mock, since the test is verifying an interaction happened correctly, not just checking a returned value","is_correct":true},{"id":"b","text":"A stub, since it returns canned data","is_correct":false},{"id":"c","text":"Neither; this requires a real email service","is_correct":false},{"id":"d","text":"A stub, since mocks cannot assert on call arguments","is_correct":false}],"explanation":"A stub just supplies canned responses so a test can run; a mock's defining feature is asserting that an interaction, like a specific call with specific arguments, actually happened. Checking call arguments is exactly what a mock does."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('36e8b242-f00d-5fe3-a850-b95ce9a71af6', '00000000-0000-0000-0000-000000000001', 'mcq', 'A test replaces an async dependency with a plain Mock() instead of an AsyncMo...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('10f6aafe-3d8a-5475-9861-4ce52bc1d3bd', '36e8b242-f00d-5fe3-a850-b95ce9a71af6', 1, $json${"prompt":"A test replaces an async dependency with a plain Mock() instead of an AsyncMock(), and the code under test does await dependency(). What happens?","multiple":false,"options":[{"id":"a","text":"A TypeError is raised, since a plain Mock's return value is not awaitable","is_correct":true},{"id":"b","text":"The test passes exactly as if AsyncMock had been used","is_correct":false},{"id":"c","text":"pytest silently skips the test","is_correct":false},{"id":"d","text":"The await keyword is ignored for any mocked object automatically","is_correct":false}],"explanation":"A plain Mock returns a synchronous Mock object when called, which is not awaitable. AsyncMock exists specifically so an awaited call returns something Python's await syntax can actually work with."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

