VALUES ('eb28e5fc-530d-5b0a-88a6-2a36b76825a7', '79fffc98-d310-5c70-8b59-baf9a723b364', 1, $json${"prompt":"Why does animating `top`/`left` cost more than animating `transform` for the same visual movement?","multiple":false,"options":[{"id":"a","text":"top/left force layout, then paint, then composite on every frame; transform can be handled entirely on the GPU's compositor thread, skipping layout and paint","is_correct":true},{"id":"b","text":"top/left are deprecated CSS properties","is_correct":false},{"id":"c","text":"transform only works with CSS animations, not transitions","is_correct":false},{"id":"d","text":"There's no real performance difference","is_correct":false}],"explanation":"top/left change an element's geometry, forcing the full layout-paint-composite pipeline. transform and opacity are the two properties that can skip straight to compositing."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

