VALUES ('8db65df0-b659-5850-8ed4-5e5c5485a8db', '00000000-0000-0000-0000-000000000001', 'mcq', 'A `useFetch(url)` hook re-fetches every time `url` changes. What specifically...', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
