INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('83bef6c3-50a8-56d2-8683-5ae4af24e783', 'a7ef124a-2110-5411-811d-b4cc8a60cb57', 1, $json${"prompt":"A component built with `withAuth(withTheme(withLogging(Component)))` is hard to debug in React DevTools. What's the underlying problem, and what's the modern replacement?","multiple":false,"options":[{"id":"a","text":"Each HOC adds a real wrapping component, producing deeply nested 'wrapper hell' that obscures prop flow, and HOCs can silently clobber each other's injected props; hooks replace this with no wrapping components at all","is_correct":true},{"id":"b","text":"The problem is a memory leak, fixed by removing withLogging","is_correct":false},{"id":"c","text":"HOCs are deprecated and will not run in React 18","is_correct":false},{"id":"d","text":"The fix is to always order HOCs alphabetically","is_correct":false}],"explanation":"Every HOC in the chain wraps the component in another real component, which is what makes DevTools hard to trace and lets two HOCs injecting the same prop name silently collide. Calling the equivalent hooks directly inside the component removes both problems."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('92a0ad8f-3ed3-5143-a9ad-2741e0bbabdc', '00000000-0000-0000-0000-000000000001', 'mcq', 'Why does `key={index}` break when a list can be reordered, but work fine for ...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
