INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('bd8b16b3-64af-5471-b3eb-d3d72512ad43', '92a0ad8f-3ed3-5143-a9ad-2741e0bbabdc', 1, $json${"prompt":"Why does `key={index}` break when a list can be reordered, but work fine for a list that never reorders or has items removed from the middle?","multiple":false,"options":[{"id":"a","text":"React matches siblings by key across renders; when items reorder, an index-based key shifts identity, so local state (like a focused input) attaches to the wrong row","is_correct":true},{"id":"b","text":"index keys are always invalid syntax in JSX","is_correct":false},{"id":"c","text":"index keys cause a memory leak regardless of reordering","is_correct":false},{"id":"d","text":"It doesn't break, index keys are always safe to use","is_correct":false}],"explanation":"A key only needs to be stable across renders for the elements it's attached to. If the list order or membership never changes, an index-based key happens to stay stable too. Reordering breaks that assumption immediately."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

