INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('b0570a9a-4f74-5559-abce-b2eb73ca280a', 'd013f42a-9c73-592e-be65-3a53ef6a6f45', 1, $json${"prompt":"When does `useMemo` actually help, as opposed to adding overhead for no real benefit?","multiple":false,"options":[{"id":"a","text":"Only when the computed value is genuinely expensive, or its reference identity feeds a React.memo-wrapped child or another hook's dependency array","is_correct":true},{"id":"b","text":"Any time a value is derived from props or state","is_correct":false},{"id":"c","text":"Only inside class components","is_correct":false},{"id":"d","text":"Only when the value is a primitive, like a number or string","is_correct":false}],"explanation":"useMemo pays a dependency-comparison cost on every render. It only pays off when the computation itself is expensive, or when a stable reference is specifically needed downstream, not as a reflexive habit applied to every derived value."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

