INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('4a08ba61-f344-5d9c-bb94-e6f56e55effe', '606ff9fd-a801-52fb-bd06-420d06e21b80', 1, $json${"prompt":"What's the practical difference between `unknown` and `any` in TypeScript?","multiple":false,"options":[{"id":"a","text":"any disables type checking entirely; unknown still requires a narrowing check before use, so mistakes surface at compile time instead of at runtime","is_correct":true},{"id":"b","text":"They are interchangeable in every context","is_correct":false},{"id":"c","text":"unknown can only be used for numbers","is_correct":false},{"id":"d","text":"any is stricter than unknown","is_correct":false}],"explanation":"any opts a value out of type checking completely. unknown is the type-safe counterpart: you can assign anything to it, but you must narrow its type (with a type guard, assertion, or check) before doing anything with it."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

