INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('da6f7279-a08f-58b3-bdd2-549cc3c9339a', '4e82a710-38ef-5dfc-946b-1e077014afdf', 1, $json${"prompt":"What problem does `React.lazy` combined with `Suspense` actually solve?","multiple":false,"options":[{"id":"a","text":"It reduces the initial JavaScript bundle size by deferring the code for routes or components not needed on first paint until they're actually rendered","is_correct":true},{"id":"b","text":"It makes every component render faster once loaded","is_correct":false},{"id":"c","text":"It eliminates the need for a build step entirely","is_correct":false},{"id":"d","text":"It replaces the need for a key prop on lists","is_correct":false}],"explanation":"React.lazy splits a component into its own chunk, loaded on demand, and Suspense shows a fallback while that chunk downloads. The win is a smaller initial bundle, not faster rendering once the code is loaded."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

