INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('5daec169-c2ec-523b-b8f6-a07ae4ff2a0a', 'e1c557be-0f49-5a2c-8c57-ab630eed19d2', 1, $json${"prompt":"A subtree's root element changes from `\u003cdiv\u003e` to `\u003cspan\u003e` between renders. What does React do?","multiple":false,"options":[{"id":"a","text":"It tears down the entire old subtree, running cleanup effects, and mounts a brand-new one, without trying to reconcile the children at all","is_correct":true},{"id":"b","text":"It patches only the tag name, keeping all child state intact","is_correct":false},{"id":"c","text":"It throws a runtime error, since element types can't change","is_correct":false},{"id":"d","text":"It ignores the change entirely and keeps rendering the old element","is_correct":false}],"explanation":"A changed element type is one of reconciliation's two core heuristics: matching type is a precondition for diffing children at all. A type change forces a full unmount (with cleanup) and a full fresh mount, discarding any local state the old subtree held."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

