INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('6b625942-6cf1-5ae1-add8-73c6a9bdcace', '6ea143d5-4e2a-5181-9eaa-aa6e167a28bd', 1, $json${"prompt":"What's the most common trap when mapping a class component's lifecycle onto `useEffect` in a function component?","multiple":false,"options":[{"id":"a","text":"Forgetting the cleanup function — listeners, subscriptions, and timers that were torn down automatically in componentWillUnmount now need an explicit returned cleanup function, or they leak","is_correct":true},{"id":"b","text":"useEffect cannot run any asynchronous code","is_correct":false},{"id":"c","text":"useEffect runs before the render instead of after","is_correct":false},{"id":"d","text":"Function components can't subscribe to external events at all","is_correct":false}],"explanation":"componentWillUnmount was a dedicated, unmissable lifecycle method for cleanup. useEffect folds that into an optional returned function, which is easy to simply forget to write, silently leaving subscriptions and timers running after unmount."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
