VALUES ('8d18e372-fb7c-5a18-a6d9-dcbddb038e6f', '00000000-0000-0000-0000-000000000001', 'mcq', 'An app stores its auth token in memory and attaches it manually through an Au...', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
