INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('5eb26841-f89c-5bdb-a063-e4da3505dead', '8d18e372-fb7c-5a18-a6d9-dcbddb038e6f', 1, $json${"prompt":"An app stores its auth token in memory and attaches it manually through an Authorization header on every request, never in a cookie. Is this token exposed to a CSRF attack?","multiple":false,"options":[{"id":"a","text":"No — CSRF exploits the browser's automatic cookie attachment; a forged cross-site form can neither read the token nor set a custom Authorization header itself","is_correct":true},{"id":"b","text":"Yes, exactly as exposed as a cookie-based token would be","is_correct":false},{"id":"c","text":"Only if the site also uses CORS","is_correct":false},{"id":"d","text":"Only on mobile browsers","is_correct":false}],"explanation":"CSRF specifically relies on the browser attaching credentials for you. A manually-attached header can't be replicated by a forged form, so this setup is safe from CSRF, though it does trade that for exposure to XSS instead, since anything in memory or storage is readable by an injected script."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

