INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('4e340d78-5101-5c0c-871a-7c273c6de493', 'ced43651-1396-58f4-b154-96d2a7a1a058', 1, $json${"prompt":"A WebSocket client's onclose handler checks event.code === 1000 before deciding whether to reconnect. Why?","multiple":false,"options":[{"id":"a","text":"Code 1000 means the connection closed normally and on purpose; every other code means something unexpected happened, so only those should trigger a reconnect","is_correct":true},{"id":"b","text":"Code 1000 means the server rejected the connection outright","is_correct":false},{"id":"c","text":"This check has no real effect on reconnection behavior","is_correct":false},{"id":"d","text":"1000 is the code for a successful message delivery, unrelated to closing","is_correct":false}],"explanation":"Without this check, either an intentional close triggers an unwanted reconnect loop, or a genuine drop looks identical to a clean close and never gets recovered. The close code is what tells the two apart."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
