INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('b24857bd-e759-596a-ab6c-671d7b3982f2', '2e454a47-ee3f-5f5c-905b-09b81d355db4', 1, $json${"prompt":"A component reads Math.random() directly during render to pick a background color, and gets a hydration mismatch warning. Why?","multiple":false,"options":[{"id":"a","text":"The server and the client each generate a different random value during their own render, so the server's HTML never matches the client's first render output","is_correct":true},{"id":"b","text":"Math.random() is not allowed anywhere in a React component","is_correct":false},{"id":"c","text":"The component needs a key prop","is_correct":false},{"id":"d","text":"Hydration warnings are unrelated to what happens during render","is_correct":false}],"explanation":"A hydration mismatch happens whenever the server's HTML and the client's own first render disagree. Math.random() during render is a classic cause, since the server and client each compute their own independent random value."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

