INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('108e44f4-72eb-5650-8b14-98a92408beaa', '88e0f47e-6f7c-5f87-9b2e-c64e3c07e396', 1, $json${"prompt":"A shell app and a remote app are composed with Module Federation, but neither marks react as a shared singleton. What breaks?","multiple":false,"options":[{"id":"a","text":"Invalid hook call errors, since the shell and the remote each ship their own separate copy of React managing what's supposed to be one component tree","is_correct":true},{"id":"b","text":"Nothing, this is the normal and recommended setup","is_correct":false},{"id":"c","text":"Only CSS styling conflicts occur","is_correct":false},{"id":"d","text":"The build fails to compile","is_correct":false}],"explanation":"Without singleton: true, each side bundles its own React. Two separate React instances can't correctly share one component tree, which is exactly what causes Invalid hook call errors."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('0fffdd5d-b5fc-5300-8f03-5e05271d85b6', '00000000-0000-0000-0000-000000000001', 'mcq', 'Why does a CommonJS require() call generally defeat tree shaking, while an ES...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('a2d67517-8487-57ce-b32f-c6c2f890a3b3', '0fffdd5d-b5fc-5300-8f03-5e05271d85b6', 1, $json${"prompt":"Why does a CommonJS require() call generally defeat tree shaking, while an ES module import doesn't?","multiple":false,"options":[{"id":"a","text":"require() calls can be conditional or built dynamically, so a bundler can't statically prove what's actually used without running the code; import/export are readable without running anything","is_correct":true},{"id":"b","text":"CommonJS modules are always larger in file size","is_correct":false},{"id":"c","text":"require() is deprecated and produces a build error","is_correct":false},{"id":"d","text":"Tree shaking only works on TypeScript files, never plain JavaScript","is_correct":false}],"explanation":"Tree shaking depends on being able to prove, just by reading the code, which exports are actually used. ES module import/export statements are statically readable; a require() call can be wrapped in a condition, which a bundler can't safely reason about ahead of time."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

