INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('3e154188-3644-503f-b5a3-48ca64f7ff7f', '0b20ccff-bf53-577d-8237-4e5af577cc55', 1, $json${"prompt":"A developer builds a clickable element with \u003cdiv role=\"button\" onClick={...}\u003e instead of a real \u003cbutton\u003e. What are they still responsible for adding themselves?","multiple":false,"options":[{"id":"a","text":"Keyboard focusability and activation on Enter/Space, since role=\"button\" only describes the semantics, it grants none of a real button's built-in behavior","is_correct":true},{"id":"b","text":"Nothing, role=\"button\" makes the div behave exactly like a real button","is_correct":false},{"id":"c","text":"Only the visual button styling","is_correct":false},{"id":"d","text":"A separate ARIA label, since role alone conflicts with onClick","is_correct":false}],"explanation":"ARIA's own first rule is not to reach for ARIA when a native element already does the job. A div with role=\"button\" still needs tabIndex, a keydown handler, and focus styling added by hand to match what a real \u003cbutton\u003e gives for free."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

