INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('01b257af-6775-593e-9b38-0d938378860e', 'c80e3aa3-a329-5f1a-91fb-93d750b8bd07', 1, $json${"prompt":"An unhandled promise rejection occurs from a fetch call with no .catch() anywhere. Which mechanism is responsible for catching it in a production app?","multiple":false,"options":[{"id":"a","text":"The nearest React error boundary in the component tree","is_correct":false},{"id":"b","text":"A window.addEventListener(\"unhandledrejection\", ...) listener, since a rejected promise falls entirely outside what an error boundary can intercept","is_correct":true},{"id":"c","text":"React's Suspense boundary","is_correct":false},{"id":"d","text":"Nothing can catch this; it always crashes the app silently","is_correct":false}],"explanation":"Error boundaries only catch errors thrown during rendering. An unhandled promise rejection is exactly the async gap they can't cover, which is what the unhandledrejection browser event exists to catch."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

