VALUES ('cca35505-3cb4-5483-a99b-004ee27c267a', '00000000-0000-0000-0000-000000000001', 'mcq', 'A pluralization check written as count === 1 ? "item" : "items" works fine fo...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
