INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('e17b430b-9b67-5fe7-9d0c-aeab000d5b6c', 'cca35505-3cb4-5483-a99b-004ee27c267a', 1, $json${"prompt":"A pluralization check written as count === 1 ? \"item\" : \"items\" works fine for English. Why does it fail for languages like Russian or Polish?","multiple":false,"options":[{"id":"a","text":"Those languages have more than two grammatical plural forms depending on the exact count, which a binary singular/plural check can't represent; ICU MessageFormat and Intl.PluralRules handle this correctly","is_correct":true},{"id":"b","text":"Those languages don't support pluralization at all","is_correct":false},{"id":"c","text":"The check fails only because of character encoding issues","is_correct":false},{"id":"d","text":"This check actually works fine in every language","is_correct":false}],"explanation":"Many languages have plural categories beyond just singular and plural, one, few, many, other. ICU MessageFormat's plural syntax and Intl.PluralRules apply the correct category for each locale automatically, where a hardcoded binary check can't generalize."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('8f283639-b52f-5099-8882-0bbf36f2a45e', '00000000-0000-0000-0000-000000000001', 'mcq', 'Why does animating transform stay smooth even while a heavy synchronous JavaS...', 'beginner', 5, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('baa8ef23-d2b4-56d0-8703-4e6459b0f75d', '8f283639-b52f-5099-8882-0bbf36f2a45e', 1, $json${"prompt":"Why does animating transform stay smooth even while a heavy synchronous JavaScript computation is running, but animating top does not?","multiple":false,"options":[{"id":"a","text":"transform can be handled entirely on the browser's compositor thread, separate from the main thread the JavaScript is running on; top requires layout and paint on the main thread on every frame","is_correct":true},{"id":"b","text":"top is a deprecated CSS property with no browser support left","is_correct":false},{"id":"c","text":"There is no real difference between the two","is_correct":false},{"id":"d","text":"transform only works inside a requestAnimationFrame callback","is_correct":false}],"explanation":"transform and opacity are the two properties that can skip straight to the compositor thread. Any property that affects layout, like top, forces the full style-layout-paint-composite pipeline on the main thread every frame, the same thread the heavy computation is occupying."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

