INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('87439a7f-acde-5352-b4b3-0b8a6c427241', 'a3c28d0a-3835-5125-902a-52cb1a6a2d5d', 1, $json${"prompt":"A dashboard polls five independent widgets, and three of them request overlapping data. What fixes the duplicate network requests, and what separately fixes the wasted re-render cost?","multiple":false,"options":[{"id":"a","text":"A query library's cache, keyed by something like queryKey, dedupes the overlapping in-flight requests; avoiding a full array replacement (diffing or memoizing per-row) fixes the wasted re-renders","is_correct":true},{"id":"b","text":"Both problems are fixed by the exact same technique: wrapping every widget in React.memo","is_correct":false},{"id":"c","text":"Increasing the polling interval fixes both problems completely","is_correct":false},{"id":"d","text":"Nothing can fix duplicate requests across independent components","is_correct":false}],"explanation":"These are two separate problems needing two separate fixes. A query library's request deduplication (by cache key) stops the redundant network calls; avoiding a full state replacement, or memoizing what doesn't need to change, is what stops the unnecessary re-renders."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('a559f693-1340-5d68-8c24-1b6a4585d834', '00000000-0000-0000-0000-000000000001', 'mcq', 'A large, unrelated list re-renders on every keystroke in a search box elsewhe...', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET type=EXCLUDED.type, title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('9f8638ad-3ce5-5055-af96-898e7a0ea90a', 'a559f693-1340-5d68-8c24-1b6a4585d834', 1, $json${"prompt":"A large, unrelated list re-renders on every keystroke in a search box elsewhere on the page. What's the most direct fix?","multiple":false,"options":[{"id":"a","text":"Move the search box's state into its own component (or memoize the list with React.memo) so a re-render caused by typing doesn't cascade into the unrelated list","is_correct":true},{"id":"b","text":"Wrap the entire page in Suspense","is_correct":false},{"id":"c","text":"Switch the search input from controlled to uncontrolled, which fixes this automatically","is_correct":false},{"id":"d","text":"This can only be fixed by rewriting the list with a class component","is_correct":false}],"explanation":"By default, a parent re-rendering cascades to every child. Colocating the search box's state so it doesn't live above the list, or wrapping the list in React.memo so an unrelated state change doesn't affect it, is what actually stops the cascade."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

