VALUES ('cca424f3-b3b4-58e6-92af-a5bd3c91b799', '5313751c-7225-5e74-8b60-bda45154273e', 1, $json${"prompt":"What is the STAR format for behavioral answers?","multiple":false,"options":[{"id":"a","text":"Situation, Task, Action, Result","is_correct":true},{"id":"b","text":"Strengths, Talents, Achievements, References","is_correct":false},{"id":"c","text":"Summary, Timeline, Analysis, Reflection","is_correct":false},{"id":"d","text":"Situation, Team, Attitude, Response","is_correct":false}],"explanation":"STAR keeps behavioral answers concrete and scoped: set the scene briefly, state your responsibility, spend most of the time on YOUR actions, and land on a measurable result."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
