VALUES ('8a0f0da4-2579-5fd6-b015-e59b30f37fbc', '023fcdbd-f9da-53f9-8a8a-067ab76cec0e', 1, $json${"prompt":"Roughly what share of a STAR answer should be the Action section?","multiple":false,"options":[{"id":"a","text":"About 60%, since it's the part interviewers are actually scoring","is_correct":true},{"id":"b","text":"About 10%, since Situation and Result matter more","is_correct":false},{"id":"c","text":"It should be split evenly across all four letters","is_correct":false},{"id":"d","text":"Action should be skipped if the Result is strong enough","is_correct":false}],"explanation":"Situation and Task combined should be about 20%, Action about 60%, and Result about 20%. If Action isn't the biggest slice, the story is built backwards."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
