VALUES ('3c7bf1e8-044c-5108-a64f-eafc28b1c7ad', '1c89d2c2-0319-5430-8813-3fe425d22943', 1, $json${"prompt":"In the Action section of a STAR story, why does using \"I\" instead of \"we\" matter?","multiple":false,"options":[{"id":"a","text":"It lets the interviewer tell what you personally did, separate from what the team did","is_correct":true},{"id":"b","text":"It makes the story sound more confident, regardless of what actually happened","is_correct":false},{"id":"c","text":"\"We\" is grammatically incorrect in interview answers","is_correct":false},{"id":"d","text":"It doesn't matter as long as the Result has a number","is_correct":false}],"explanation":"A behavioral interview is scoring you, not your team. \"We\" throughout the Action section hides exactly the information the interviewer needs."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
