VALUES ('77d33b97-2cb3-5b56-8398-e70bd5aa9fa5', '122cad93-97dd-5619-88ab-3c0e09d91a2b', 1, $json${"prompt":"The night before the interview, the right move is:","multiple":false,"options":[{"id":"a","text":"Brief pattern skim, prepare clothes/setup, full night of sleep","is_correct":true},{"id":"b","text":"An all-nighter reviewing every topic once more","is_correct":false},{"id":"c","text":"Three timed mock interviews to stay sharp","is_correct":false},{"id":"d","text":"Learning that one system design topic you skipped","is_correct":false}],"explanation":"Sleep consolidates memory and powers the working memory you'll lean on tomorrow. Trading it for one more pass is strictly negative expected value."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
